// 买x张选票能否更优
ll check(int x)
{
    // 花费代价
    ll ret=0;
    // 拥有的票数
    int tot=0;
    vector<int> tmp;
    for(int i=1;i<=m;++i)
    {
        int j=0,k=v[i].size();
        // 让所有人小于等于x张票
        while(k>=x) 
            ret+=v[i][j++],--k,++tot;
        // 可选票候选集中  
        while(j<v[i].size()) 
            tmp.push_back(v[i][j++]);
    }
    sort(tmp.begin(),tmp.end());
    for(int i=0;i<tmp.size();++i)
    {
        if(tot>=x) 
            break;
        ret+=tmp[i],++tot;
    }
    return ret;
}
