#include <bits/stdc++.h>
#include <queue>
using namespace std;
const int MAXN = 3005;
​
// tree1[i]：支持店铺 i 的所有票价
vector<int> tree1[MAXN];
// f[i]：每个店铺第 i 张便宜的票集合
vector<int> f[MAXN];
​
bool cmp(int x, int y) {
    return x > y;
}
​
int main() {
    int n,m;
    scanf("%d,%d", &n, &m);
    int max_a = 0, max_b = 1;
    long long result = 0;
​
    // 输入处理
    for (int i = 0; i < n; ++i) {
        int x, y;
        scanf("%d,%d", &x,&y);
        // 最大店铺
        max_a = max(max_a, x);
        // 投给1号不考虑
        if (x == 1) continue;
        // 最大值
        max_b = max(max_b, y);
        result += y;
        tree1[x].push_back(y);
    }

    // 对每个店铺的支持票价进行排序，并按位置填入 f[]
    for (int i = 1; i <= max_a; ++i) {
        if (!tree1[i].empty()) {
            sort(tree1[i].begin(), tree1[i].end(), cmp);
            for (int j = 0; j < (int)tree1[i].size(); ++j) {
                f[j + 1].push_back(tree1[i][j]);
            }
        }
    }
​
    // 初始我拥有所有票
    int k = n;
    // 初始我拥有所有票的花费
    long long tmp = result;
    // 内部会自动使用进行排序
    std::multiset<int> ms;
    // 允许其它店铺有i张票
    for (int i = 1; i <= n; ++i) {
        // 手中余票减少的数量
        k -= f[i].size();
        for (int j = 0; j < (int)f[i].size(); ++j) {
           // 释放这些票 作为可补充票候选池
            ms.insert(f[i][j]);
           // 减少的花费
            tmp -= f[i][j];
        }
        long long add = 0;
        // 让所有人可以拥有i张票的情况下,我手头的票可能不足 i + 1,我需要再购买一些回来 
        if (k <= i) {
            int count = i + 1 - k;
            for (auto value : ms) {
                if (count == 0) {
                    break;
                }
                add += value;
                count--;
            }
        }
        result = min(result, tmp + add);
    }
​
    printf("%lld\n", result);
    return 0;
}
