public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] nm = sc.nextLine().split(",");
        int n = Integer.parseInt(nm[0]);
        int m = Integer.parseInt(nm[1]);
​
        List<List<Integer>> tree1 = new ArrayList<>();
        List<List<Integer>> f = new ArrayList<>();
        for (int i = 0; i <= 3000; i++) {
            tree1.add(new ArrayList<>());
            f.add(new ArrayList<>());
        }
​
        int maxShop = 0;
        long result = 0;
​
        // 输入处理
        for (int i = 0; i < n; i++) {
            String[] line = sc.nextLine().split(",");
            int x = Integer.parseInt(line[0]);
            int y = Integer.parseInt(line[1]);
            maxShop = Math.max(maxShop, x);
            if (x == 1) continue; // 投给1号不考虑
            result += y;
            tree1.get(x).add(y);
        }
​
        // 对每个店铺的票价排序，并按位置填入 f[i]
        for (int i = 1; i <= maxShop; i++) {
            List<Integer> list = tree1.get(i);
            if (!list.isEmpty()) {
                list.sort(Collections.reverseOrder()); // 降序
                for (int j = 0; j < list.size(); j++) {
                    f.get(j + 1).add(list.get(j));
                }
            }
        }
​
        int k = n;
        long tmp = result;
        // 使用map快速求出n 张最低价格
        TreeMap<Integer, Integer> ms = new TreeMap<>();
​
        // 尝试允许其他店铺最多拥有 i 张票
        for (int i = 1; i <= n; i++) {
            k -= f.get(i).size();
            for (int price : f.get(i)) {
                // 释放这些票进入可补充池
                ms.put(price, ms.getOrDefault(price, 0) + 1);
                tmp -= price;
            }
​
            long add = 0;
            if (k <= i) {
                int count = i + 1 - k;
​
                // 遍历前 count 个最小值
                for (Map.Entry<Integer, Integer> entry : ms.entrySet()) {
                    int price = entry.getKey();
                    int freq = entry.getValue();
​
                    int take = Math.min(count, freq);
                    add += (long) take * price;
                    count -= take;
                    if (count == 0) break;
                }
            }
            result = Math.min(result, tmp + add);
        }
​
        System.out.println(result);
    }
}
