import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
var n, m int
var v [][]int
​
// 检查买 x 张选票是否更优
func check(x int) int64 {
    var ret int64 = 0 // 总花费
    tot := 0          // 当前已获得的选票数
    tmp := []int{}    // 可选择的选票代价集合
​
    for i := 1; i <= m; i++ {
        group := v[i]
        j := 0
        k := len(group)
        // 让所有人小于等于 x 张票，强制买走多的票
        for k >= x {
            ret += int64(group[j])
            j++
            k--
            tot++
        }
        // 剩下的票进入可选集
        tmp = append(tmp, group[j:]...)
    }
​
    // 从小到大选择最便宜的票
    sort.Ints(tmp)
    for _, cost := range tmp {
        if tot >= x {
            break
        }
        ret += int64(cost)
        tot++
    }
    return ret
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取第一行：n,m
    scanner.Scan()
    parts := strings.Split(scanner.Text(), ",")
    n, _ = strconv.Atoi(parts[0])
    m, _ = strconv.Atoi(parts[1])
​
    // 初始化投票数组
    v = make([][]int, m+1)
    for i := 0; i < n; i++ {
        // 每一行是 p,c
        scanner.Scan()
        parts = strings.Split(scanner.Text(), ",")
        p, _ := strconv.Atoi(parts[0])
        c, _ := strconv.Atoi(parts[1])
        v[p] = append(v[p], c)
    }
​
    // 按照购物补贴代价排序
    for i := 1; i <= m; i++ {
        sort.Ints(v[i])
    }
​
    // 直接给 1 号店投票代价全设为 0
    for i := range v[1] {
        v[1][i] = 0
    }
​
    // 二分搜索最优投票数量
    l, r := 1, n
    for l <= r {
        mid := (l + r) / 2
        if check(mid) < check(mid+1) {
            r = mid - 1
        } else {
            l = mid + 1
        }
    }
​
    // 输出最小代价
    fmt.Println(check(l))
}
