package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
func main() {
    const MAXN = 3005
    reader := bufio.NewReader(os.Stdin)
​
    line, _ := reader.ReadString('\n')
    line = strings.TrimSpace(line)
    parts := strings.Split(line, ",")
    n, _ := strconv.Atoi(parts[0])
    // m, _ := strconv.Atoi(parts[1])
    // tree1[i]：支持店铺 i 的所有票价
    tree1 := make([][]int, MAXN)
    //f[i]：每个店铺第 i 张便宜的票集合
    f := make([][]int, MAXN)
    for i := 0; i < MAXN; i++ {
        tree1[i] = []int{}
        f[i] = []int{}
    }
​
    maxShop := 0
    var result int64 = 0
​
    for i := 0; i < n; i++ {
        line, _ := reader.ReadString('\n')
        line = strings.TrimSpace(line)
        parts := strings.Split(line, ",")
        x, _ := strconv.Atoi(parts[0])
        y, _ := strconv.Atoi(parts[1])
        if x == 1 {
            continue
        }
        if x > maxShop {
            maxShop = x
        }
        result += int64(y)
        tree1[x] = append(tree1[x], y)
    }

    for i := 1; i <= maxShop; i++ {
        if len(tree1[i]) > 0 {
            sort.Slice(tree1[i], func(a, b int) bool {
                return tree1[i][a] > tree1[i][b] // 降序
            })
            for j, val := range tree1[i] {
                f[j+1] = append(f[j+1], val)
            }
        }
    }
​
    // 初始获得所有选票
    k := n
    // 所有选票的代价
    tmp := result
    ms := []int{}
​
    for i := 1; i <= n; i++ {
        k -= len(f[i])
        // 释放其它店铺选票
        for _, price := range f[i] {
            // 插入有序位置（手动插入）
            pos := sort.SearchInts(ms, price)
            ms = append(ms, 0)
            copy(ms[pos+1:], ms[pos:])
            ms[pos] = price
            tmp -= int64(price)
        }
​
        var add int64 = 0
        // 回购票
        if k <= i {
            count := i + 1 - k
            for j := 0; j < count && j < len(ms); j++ {
                add += int64(ms[j])
            }
        }
        // 更新结果
        if tmp+add < result {
            result = tmp + add
        }
    }
​
    fmt.Println(result)
}
